-- Dream Track extends existing course identities, enrollments, answers and progress.
-- Answer keys/configuration are RPC-only; public HTML contains no grading keys.
begin;
insert into public.courses(slug,title,description,total_lessons) values('dream-track','Dream Track','WATCH + PASS TO ADVANCE',7);
create table public.course_settings(
 course_id bigint primary key references public.courses(id), organization_id uuid not null references public.organizations(id),
 access_hash text, access_salt text, access_active boolean not null default false, updated_at timestamptz not null default now(),
 unique(organization_id,course_id));
insert into public.course_settings(course_id,organization_id) select c.id,o.id from public.courses c cross join public.organizations o where c.slug='dream-track' and o.slug='champion-life';
create table public.course_lessons(
 course_id bigint not null references public.course_settings(course_id), lesson_number integer not null check(lesson_number between 1 and 7),
 title text not null, video_id text not null, duration_seconds integer not null check(duration_seconds>0), primary key(course_id,lesson_number));
insert into public.course_lessons select c.id,v.* from public.courses c cross join(values
 (1,'Dream Track Intro','G2g3MhR7z2w',1925),(2,'God’s Dream','rvY373QWI0w',4350),(3,'New Birth','FQLZ4IU87_U',3685),
 (4,'Holy Spirit','3a58NYEvaE4',5005),(5,'Healing','qc4-wikNlkM',5580),(6,'Abundant Life','FzFSBOZUn5k',5940),(7,'Church Government','jKlgOyyJXAQ',3930)
)v(lesson_number,title,video_id,duration_seconds) where c.slug='dream-track';
create table public.course_questions(
 course_id bigint not null, lesson_number integer not null, question_number integer not null check(question_number between 1 and 20),
 version integer not null default 1, active boolean not null default true, display_order integer not null, kind text not null default 'fill_blank' check(kind='fill_blank'),
 prompt text not null, correct_answer text not null, accepted_variants text[] not null, review_start integer not null check(review_start>=0), review_end integer not null check(review_end>review_start), scripture_reference text,
 primary key(course_id,lesson_number,question_number,version), foreign key(course_id,lesson_number) references public.course_lessons);
create unique index course_questions_current on public.course_questions(course_id,lesson_number,question_number) where active;
alter table public.lesson_progress add column watched_ranges nummultirange not null default '{}', add column resume_seconds numeric not null default 0,
 add column watch_token uuid, add column watch_at timestamptz, add column watch_anchor numeric, add column first_submitted_at timestamptz, add column best_score integer not null default 0;
alter table public.lesson_answers add column mastered_at timestamptz;
create table public.course_attempts(
 id bigint generated always as identity primary key, enrollment_id bigint not null references public.course_enrollments(id), lesson_number integer not null, question_number integer not null,
 question_version integer not null, submitted_value text not null, correct boolean not null, resulting_mastery integer not null, remediation_start integer not null, remediation_end integer not null,
 request_id uuid not null, submitted_at timestamptz not null default clock_timestamp(), unique(enrollment_id,request_id,question_number));
create index course_attempts_lesson on public.course_attempts(enrollment_id,lesson_number,id);
create table public.course_completions(
 enrollment_id bigint primary key references public.course_enrollments(id), person_id uuid references public.organization_people(id),
 online_completed_at timestamptz, meeting_completed_at timestamptz, meeting_completed_by uuid references auth.users(id),
 meeting_note text, badge_awarded_at timestamptz, badge_revoked_at timestamptz, revision integer not null default 1);
create table public.course_invites(
 id uuid primary key default gen_random_uuid(), course_id bigint not null references public.course_settings(course_id), recipient_email text not null, recipient_name text not null default '',
 person_id uuid references public.organization_people(id), token_hash text not null unique,
 status text not null default 'pending' check(status in('pending','sent','accepted','expired','cancelled','failed')),
 invited_by uuid not null references auth.users(id), invited_at timestamptz not null default now(), expires_at timestamptz not null default now()+interval '7 days',
 accepted_user uuid references auth.users(id), accepted_at timestamptz, send_status text not null default 'not_sent', resend_count integer not null default 0,
 delivery_id uuid not null default gen_random_uuid(), last_send_at timestamptz);
create index course_invites_course on public.course_invites(course_id,invited_at);
create table public.course_audit(
 id bigint generated always as identity primary key, course_id bigint not null references public.course_settings(course_id), enrollment_id bigint references public.course_enrollments(id),
 invite_id uuid references public.course_invites(id), actor_user_id uuid references auth.users(id), action text not null, metadata jsonb not null default '{}', created_at timestamptz not null default clock_timestamp());
create index course_audit_course on public.course_audit(course_id,id);
create table public.course_claim_limits(user_id uuid primary key references auth.users(id), window_start timestamptz not null, attempts integer not null);
-- Prevent bypass via the original generic self-service course tables, including moving a Grip row into Dream Track.
do $$declare t text; prefix text; begin
 for t,prefix in select * from(values('course_enrollments','enrollments'),('lesson_progress','progress'),('lesson_answers','answers'))v(t,p) loop
  execute format('drop policy %I on public.%I',prefix||'_insert_own',t);
  execute format('drop policy %I on public.%I',prefix||'_update_own',t);
  execute format('create policy %I on public.%I for insert to authenticated with check ((select auth.uid())=user_id and course_id in(select id from public.courses where slug<>''dream-track''))',prefix||'_insert_own',t);
  execute format('create policy %I on public.%I for update to authenticated using ((select auth.uid())=user_id and course_id in(select id from public.courses where slug<>''dream-track'')) with check ((select auth.uid())=user_id and course_id in(select id from public.courses where slug<>''dream-track''))',prefix||'_update_own',t);
 end loop;
end $$;
create function private.course_normalize(v text) returns text language sql immutable set search_path='' as $$
 select lower(regexp_replace(btrim(v),'[[:space:][:punct:]‘’“”–—]+','','g'))
$$;
-- Salted, iterated SHA-256 for human-entered codes; random invitation tokens use SHA-256 directly.
create function private.course_code_hash(v text,s text) returns text language plpgsql immutable set search_path='' as $$
declare h bytea:=convert_to(s||v,'UTF8'); i integer; begin for i in 1..10000 loop h:=sha256(h||convert_to(s,'UTF8')); end loop; return encode(h,'hex');end $$;
create function private.course_immutable() returns trigger language plpgsql set search_path='' as $$begin raise exception 'Course history is immutable';end $$;
create trigger course_attempts_immutable before update or delete on public.course_attempts for each row execute function private.course_immutable();
create trigger course_audit_immutable before update or delete on public.course_audit for each row execute function private.course_immutable();
create function private.course_snapshot(p_course bigint,p_user uuid,p_lesson integer default null) returns jsonb language sql stable set search_path='' as $$
 select jsonb_build_object('course_id',p_course,'enrolled',e.id is not null,'enrollment_id',e.id,'completion',to_jsonb(c)-'meeting_note'-'meeting_completed_by'-'person_id',
 'status',case when c.badge_awarded_at is not null and c.badge_revoked_at is null then 'Dream Track Completed' when c.online_completed_at is not null then 'ONLINE COURSEWORK COMPLETE – FINAL MEETING REQUIRED' when e.id is not null then 'In progress' else 'Access code or invitation required' end,
 'lessons',(select jsonb_agg(jsonb_build_object('number',l.lesson_number,'title',l.title,'video_id',case when e.id is not null then l.video_id end,'duration',l.duration_seconds,
 'unlocked',e.id is not null and (l.lesson_number=1 or exists(select 1 from public.lesson_progress prev where prev.course_id=p_course and prev.user_id=p_user and prev.lesson_number=l.lesson_number-1 and prev.status='completed')),
 'status',coalesce(p.status,'not_started'),'watched_percent',coalesce((select sum(upper(r)-lower(r))*100.0/l.duration_seconds from unnest(p.watched_ranges)r),0),
 'resume_seconds',coalesce(p.resume_seconds,0),'mastered',(select count(*) from public.lesson_answers a where a.course_id=p_course and a.user_id=p_user and a.lesson_number=l.lesson_number and a.mastered_at is not null),
 'best_score',coalesce(p.best_score,0),'first_submitted_at',p.first_submitted_at,'passed_at',p.completed_at,'last_activity',p.updated_at)
 order by l.lesson_number) from public.course_lessons l left join public.lesson_progress p on p.course_id=l.course_id and p.lesson_number=l.lesson_number and p.user_id=p_user where l.course_id=p_course),
 'questions',case when p_lesson is null or e.id is null then '[]'::jsonb else (select coalesce(jsonb_agg(jsonb_build_object('number',q.question_number,'prompt',q.prompt,'kind',q.kind,'review_start',q.review_start,'review_end',q.review_end,'scripture',q.scripture_reference,'answer',coalesce(a.answer,''),'mastered',a.mastered_at is not null,
 'attempted',exists(select 1 from public.course_attempts x where x.enrollment_id=e.id and x.lesson_number=p_lesson and x.question_number=q.question_number)) order by q.display_order),'[]') from public.course_questions q left join public.lesson_answers a on a.course_id=q.course_id and a.lesson_number=q.lesson_number and a.question_number=q.question_number and a.user_id=p_user where q.course_id=p_course and q.lesson_number=p_lesson and q.active) end,
 'notes',case when p_lesson is null then null else (select notes from public.lesson_progress where course_id=p_course and user_id=p_user and lesson_number=p_lesson) end)
 from (select 1) anchor left join public.course_enrollments e on e.course_id=p_course and e.user_id=p_user left join public.course_completions c on c.enrollment_id=e.id
$$;
create function private.course_recompute(p_course bigint,p_user uuid,p_lesson integer) returns void language plpgsql set search_path='' as $$
declare n integer; seconds numeric; duration integer; eid bigint;begin
 select id into eid from public.course_enrollments where course_id=p_course and user_id=p_user for update;
 select count(*) into n from public.lesson_answers where course_id=p_course and user_id=p_user and lesson_number=p_lesson and mastered_at is not null;
 select coalesce(sum(upper(r)-lower(r)),0) into seconds from public.lesson_progress p cross join lateral unnest(p.watched_ranges)r where p.course_id=p_course and p.user_id=p_user and p.lesson_number=p_lesson;
 select duration_seconds into duration from public.course_lessons where course_id=p_course and lesson_number=p_lesson;
 update public.lesson_progress set best_score=greatest(best_score,n*5),status=case when n>=16 and seconds*100>=duration*95 then 'completed' else status end,
 completed_at=case when n>=16 and seconds*100>=duration*95 then coalesce(completed_at,now()) else completed_at end,updated_at=clock_timestamp() where course_id=p_course and user_id=p_user and lesson_number=p_lesson;
 if (select count(*) from public.lesson_progress where course_id=p_course and user_id=p_user and status='completed')=7 then
  update public.course_completions set online_completed_at=coalesce(online_completed_at,now()),badge_awarded_at=case when meeting_completed_at is not null then coalesce(badge_awarded_at,now()) else badge_awarded_at end where enrollment_id=eid;
 end if;
end $$;
create function private.dream_track(p_action text,p_data jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid(); cid bigint; eid bigint; l integer; q record; ans text; n integer; ok boolean; rid uuid; inv public.course_invites; cfg public.course_settings; lim public.course_claim_limits;
 p public.lesson_progress; lesson public.course_lessons; pos numeric; dt numeric; token uuid; r nummultirange; result jsonb:='[]';begin
 if uid is null or not exists(select 1 from auth.users where id=uid and email_confirmed_at is not null and not coalesce(is_anonymous,false)) then raise exception 'Verified sign-in required';end if;
 if p_data is null or jsonb_typeof(p_data)<>'object' or octet_length(p_data::text)>24000 then raise exception 'Invalid request';end if;
 select id into cid from public.courses where slug='dream-track';select * into cfg from public.course_settings where course_id=cid;
 if p_action='claim_code' then
  insert into public.course_claim_limits values(uid,clock_timestamp(),0) on conflict do nothing;
  select * into lim from public.course_claim_limits where user_id=uid for update;
  if lim.window_start<clock_timestamp()-interval '15 minutes' then update public.course_claim_limits set window_start=clock_timestamp(),attempts=0 where user_id=uid;lim.attempts:=0;end if;
  if lim.attempts>=10 then return jsonb_build_object('error','Too many attempts. Try again in 15 minutes.');end if;
  update public.course_claim_limits set attempts=attempts+1 where user_id=uid;
  if length(coalesce(p_data->>'code',''))>128 or not cfg.access_active or cfg.access_hash is null or private.course_code_hash(coalesce(p_data->>'code',''),cfg.access_salt)<>cfg.access_hash then return jsonb_build_object('error','Access code not accepted.');end if;
  insert into public.course_enrollments(user_id,course_id) values(uid,cid) on conflict do nothing;
 elsif p_action='claim_invite' then
  if length(coalesce(p_data->>'token',''))<>64 then raise exception 'Invitation unavailable';end if;
  select * into inv from public.course_invites where course_id=cid and token_hash=encode(sha256(convert_to(p_data->>'token','UTF8')),'hex') for update;
  if inv.id is null or not exists(select 1 from auth.users where id=uid and lower(email)=inv.recipient_email and email_confirmed_at is not null) then raise exception 'Invitation unavailable for this verified account';end if;
  if inv.status='accepted' and inv.accepted_user=uid then return private.course_snapshot(cid,uid);end if;
  if inv.status not in('pending','sent','failed') or inv.expires_at<=now() then raise exception 'Invitation expired or cancelled';end if;
  insert into public.course_enrollments(user_id,course_id) values(uid,cid) on conflict do nothing;
  select id into eid from public.course_enrollments where user_id=uid and course_id=cid for update;
  insert into public.course_completions(enrollment_id,person_id) values(eid,inv.person_id) on conflict(enrollment_id) do nothing;
  update public.course_invites set status='accepted',accepted_user=uid,accepted_at=now() where id=inv.id;
  insert into public.course_audit(course_id,enrollment_id,invite_id,actor_user_id,action) values(cid,eid,inv.id,uid,'invite_accepted');
 elsif p_action='claim_pending' then
  for inv in select i.* from public.course_invites i join auth.users u on u.id=uid and lower(u.email)=i.recipient_email where i.course_id=cid and i.status='sent' and i.expires_at>now() order by i.id for update of i loop
   insert into public.course_enrollments(user_id,course_id) values(uid,cid) on conflict do nothing;
   select id into eid from public.course_enrollments where course_id=cid and user_id=uid for update;
   insert into public.course_completions(enrollment_id,person_id) values(eid,inv.person_id) on conflict do nothing;
   update public.course_invites set status='accepted',accepted_user=uid,accepted_at=now() where id=inv.id;
   insert into public.course_audit(course_id,enrollment_id,invite_id,actor_user_id,action)values(cid,eid,inv.id,uid,'verified_email_invite_accepted');
  end loop;
 elsif p_action not in('dashboard','lesson','save','submit','watch_start','watch_tick') then raise exception 'Unknown course action';end if;
 select id into eid from public.course_enrollments where course_id=cid and user_id=uid for update;
 if eid is not null then insert into public.course_completions(enrollment_id) values(eid) on conflict do nothing;end if;
 if p_action in('dashboard','claim_code','claim_invite','claim_pending') then return private.course_snapshot(cid,uid);end if;
 if eid is null then raise exception 'Dream Track enrollment required';end if;
 l:=(p_data->>'lesson')::integer;
 select * into lesson from public.course_lessons where course_id=cid and lesson_number=l;
 if lesson.course_id is null or (l>1 and not exists(select 1 from public.lesson_progress where user_id=uid and course_id=cid and lesson_number=l-1 and status='completed')) then raise exception 'Lesson locked';end if;
 insert into public.lesson_progress(user_id,course_id,lesson_number,status,started_at) values(uid,cid,l,'in_progress',now()) on conflict do nothing;
 select * into p from public.lesson_progress where user_id=uid and course_id=cid and lesson_number=l for update;
 if p_action in('save','submit') then
  if jsonb_typeof(coalesce(p_data->'answers','{}'))<>'object' or length(coalesce(p_data->>'notes',''))>10000 then raise exception 'Invalid worksheet';end if;
  if exists(select 1 from jsonb_each(coalesce(p_data->'answers','{}'))a where a.key !~ '^([1-9]|1[0-9]|20)$' or jsonb_typeof(a.value)<>'string' or length(a.value#>>'{}')>500) then raise exception 'Invalid answer';end if;
  if p_action='submit' then
   rid:=(p_data->>'request_id')::uuid;if rid is null then raise exception 'Submission identifier required';end if;
   if exists(select 1 from public.course_attempts where enrollment_id=eid and request_id=rid) then return private.course_snapshot(cid,uid,l);end if;
   update public.lesson_progress set first_submitted_at=coalesce(first_submitted_at,now()) where id=p.id;
  end if;
  for q in select * from public.course_questions where course_id=cid and lesson_number=l and active order by display_order loop
   if exists(select 1 from public.lesson_answers where user_id=uid and course_id=cid and lesson_number=l and question_number=q.question_number and mastered_at is not null) then continue;end if;
   if not (coalesce(p_data->'answers','{}') ? q.question_number::text) then continue;end if;
   ans:=p_data->'answers'->>q.question_number::text;
   if ans is null then raise exception 'Answer must be text';end if;
   ok:=p_action='submit' and private.course_normalize(ans)=any(array(select private.course_normalize(x) from unnest(q.accepted_variants||q.correct_answer)x));
   insert into public.lesson_answers(user_id,course_id,lesson_number,question_number,answer,mastered_at) values(uid,cid,l,q.question_number,ans,case when ok then now() end)
   on conflict(user_id,course_id,lesson_number,question_number) do update set answer=excluded.answer,mastered_at=excluded.mastered_at,updated_at=clock_timestamp();
   if p_action='submit' then
    select count(*) into n from public.lesson_answers where user_id=uid and course_id=cid and lesson_number=l and mastered_at is not null;
    insert into public.course_attempts(enrollment_id,lesson_number,question_number,question_version,submitted_value,correct,resulting_mastery,remediation_start,remediation_end,request_id) values(eid,l,q.question_number,q.version,ans,ok,n,q.review_start,q.review_end,rid);
   end if;
  end loop;
  update public.lesson_progress set notes=coalesce(p_data->>'notes',notes),updated_at=clock_timestamp() where id=p.id;
 elsif p_action in('watch_start','watch_tick') then
  pos:=(p_data->>'position')::numeric;
  if pos is null or pos::text in('NaN','Infinity','-Infinity') or pos<0 or pos>lesson.duration_seconds then raise exception 'Invalid video position';end if;
  if p_action='watch_start' then
   token:=gen_random_uuid();update public.lesson_progress set watch_token=token,watch_at=clock_timestamp(),watch_anchor=pos,resume_seconds=pos where id=p.id;
   return jsonb_build_object('watch_token',token);
  end if;
  if (p_data->>'watch_token')::uuid is distinct from p.watch_token or p.watch_token is null then raise exception 'Video session changed';end if;
  dt:=extract(epoch from clock_timestamp()-p.watch_at);
  -- Accept only short, contiguous playback bounded by real server time (up to 2x playback).
  -- A seek resets the anchor without credit. One account has one active telemetry session per lesson.
  if pos>=p.watch_anchor and pos-p.watch_anchor<=least(30,dt*2+1) and dt>=0.5 and dt<=45 then
   r:=nummultirange(numrange(p.watch_anchor,pos,'[)'));
   update public.lesson_progress set watched_ranges=watched_ranges+r where id=p.id;
  end if;
  update public.lesson_progress set watch_at=clock_timestamp(),watch_anchor=pos,resume_seconds=pos where id=p.id;
 end if;
 perform private.course_recompute(cid,uid,l);
 return private.course_snapshot(cid,uid,l);
end $$;
create function private.dream_track_admin(p_org uuid,p_action text,p_data jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare cid bigint; eid bigint; uid uuid; cfg public.course_settings; inv public.course_invites; c public.course_completions; raw text; salt text; email text; pid uuid; result jsonb;begin
 if not private.has_staff_permission(p_org,'courses.manage') then raise exception 'Organization-wide courses.manage required';end if;
 select * into cfg from public.course_settings where organization_id=p_org and course_id=(select id from public.courses where slug='dream-track');cid:=cfg.course_id;
 if cid is null then raise exception 'Course unavailable in this organization';end if;
 if p_data is null or jsonb_typeof(p_data)<>'object' or octet_length(p_data::text)>16000 then raise exception 'Invalid request';end if;
 if p_action='list' then
  return jsonb_build_object('code_exists',cfg.access_hash is not null,'code_active',cfg.access_active,
   'learners',(select coalesce(jsonb_agg(x),'[]') from(select e.id,e.user_id,u.email,concat_ws(' ',p.first_name,p.last_name) name,cmp.person_id,cmp.online_completed_at,cmp.meeting_completed_at,cmp.badge_awarded_at,cmp.badge_revoked_at,cmp.revision,
    (select max(updated_at) from public.lesson_progress where user_id=e.user_id and course_id=cid)last_activity,
    (select count(*) from public.lesson_progress where user_id=e.user_id and course_id=cid and status='completed')passed_lessons
    from public.course_enrollments e join auth.users u on u.id=e.user_id left join public.profiles p on p.user_id=e.user_id left join public.course_completions cmp on cmp.enrollment_id=e.id
    where e.course_id=cid and (coalesce(p_data->>'search','')='' or (u.email||' '||coalesce(p.first_name,'')||' '||coalesce(p.last_name,'')) ilike '%'||left(p_data->>'search',120)||'%')
    and (not coalesce((p_data->>'completed_only')::boolean,false) or (cmp.badge_awarded_at is not null and cmp.badge_revoked_at is null)) order by e.id desc limit 100 offset greatest(0,least(coalesce((p_data->>'offset')::integer,0),100000)))x),
   'invites',(select coalesce(jsonb_agg(x),'[]') from(select id,recipient_email,recipient_name,person_id,case when status in('pending','sent','failed') and expires_at<=now() then 'expired' else status end status,invited_at,invited_by,expires_at,accepted_user,accepted_at,send_status,resend_count from public.course_invites where course_id=cid order by invited_at desc limit 100)x));
 elsif p_action='people' then
  if not private.has_staff_permission(p_org,'people.read') then raise exception 'People read access required to select a contact';end if;
  return (select coalesce(jsonb_agg(x),'[]') from(select id,first_name,last_name,email from public.organization_people where organization_id=p_org and (coalesce(first_name,'')||' '||coalesce(last_name,'')||' '||coalesce(email,'')) ilike '%'||left(coalesce(p_data->>'search',''),120)||'%' order by last_name limit 30)x);
 elsif p_action='code' then
  if p_data ? 'code' then
   if length(p_data->>'code') not between 12 and 128 then raise exception 'Use a code of 12–128 characters';end if;
   salt:=gen_random_uuid()::text;update public.course_settings set access_salt=salt,access_hash=private.course_code_hash(p_data->>'code',salt),access_active=coalesce((p_data->>'active')::boolean,true),updated_at=now() where course_id=cid;
  else update public.course_settings set access_active=coalesce((p_data->>'active')::boolean,false),updated_at=now() where course_id=cid;end if;
  insert into public.course_audit(course_id,actor_user_id,action) values(cid,auth.uid(),'access_code_changed');return jsonb_build_object('saved',true);
 elsif p_action in('invite','resend','cancel') then
  if p_action='invite' then
   email:=lower(btrim(p_data->>'email'));pid:=nullif(p_data->>'person_id','')::uuid;
   if email is null or length(email)>254 or email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then raise exception 'Valid recipient email required';end if;
   if pid is not null and not exists(select 1 from public.organization_people where id=pid and organization_id=p_org) then raise exception 'Reviewed Person must belong to this organization';end if;
   -- Explicit selection never creates/merges a Person or portal link.
   raw:=replace(gen_random_uuid()::text||gen_random_uuid()::text,'-','');
   insert into public.course_invites(course_id,recipient_email,recipient_name,person_id,token_hash,invited_by)
   values(cid,email,left(coalesce(p_data->>'name',''),160),pid,encode(sha256(convert_to(raw,'UTF8')),'hex'),auth.uid()) returning * into inv;
  else
   select * into inv from public.course_invites where id=(p_data->>'invite_id')::uuid and course_id=cid for update;
   if inv.id is null or inv.status='accepted' then raise exception 'Invitation cannot be changed';end if;
   if p_action='cancel' then update public.course_invites set status='cancelled',delivery_id=gen_random_uuid() where id=inv.id;
   else
    if inv.invited_at>clock_timestamp()-interval '1 minute' or inv.last_send_at>clock_timestamp()-interval '1 minute' then raise exception 'Wait one minute before resending';end if;
    raw:=replace(gen_random_uuid()::text||gen_random_uuid()::text,'-','');
    update public.course_invites set token_hash=encode(sha256(convert_to(raw,'UTF8')),'hex'),status='pending',expires_at=now()+interval '7 days',send_status='not_sent',resend_count=resend_count+1,delivery_id=gen_random_uuid(),last_send_at=now() where id=inv.id returning * into inv;
   end if;
  end if;
  insert into public.course_audit(course_id,invite_id,actor_user_id,action) values(cid,inv.id,auth.uid(),p_action);
  return jsonb_build_object('id',inv.id,'token',raw,'recipient_email',inv.recipient_email,'delivery_id',inv.delivery_id,'status',case when p_action='cancel' then 'cancelled' else 'pending' end);
 elsif p_action in('send','send_unavailable') then
  select * into inv from public.course_invites where id=(p_data->>'invite_id')::uuid and course_id=cid for update;
  if inv.id is null or inv.status not in('pending','failed') or inv.expires_at<=now() or inv.token_hash<>encode(sha256(convert_to(coalesce(p_data->>'token',''),'UTF8')),'hex') then raise exception 'Invitation unavailable';end if;
  if p_action='send_unavailable' then
   update public.course_invites set status='failed',send_status='delivery_unavailable' where id=inv.id and send_status<>'sending';
  else
   if inv.send_status='sending' and inv.last_send_at>clock_timestamp()-interval '2 minutes' then raise exception 'Delivery already in progress';end if;
   update public.course_invites set send_status='sending',last_send_at=clock_timestamp() where id=inv.id;
  end if;
  return jsonb_build_object('id',inv.id,'recipient_email',inv.recipient_email,'delivery_id',inv.delivery_id);
 elsif p_action in('detail','meeting') then
  select id,user_id into eid,uid from public.course_enrollments where id=(p_data->>'enrollment_id')::bigint and course_id=cid for update;
  if eid is null then raise exception 'Learner unavailable';end if;
  insert into public.course_completions(enrollment_id) values(eid) on conflict do nothing;
  select * into c from public.course_completions where enrollment_id=eid for update;
  if p_action='meeting' then
   if (p_data->>'revision')::integer is distinct from c.revision then raise exception 'Learner changed. Refresh before saving.';end if;
   if coalesce((p_data->>'complete')::boolean,false) then
    if c.online_completed_at is null then raise exception 'All seven lessons must pass before final completion';end if;
    update public.course_completions set meeting_completed_at=coalesce(meeting_completed_at,now()),meeting_completed_by=coalesce(meeting_completed_by,auth.uid()),meeting_note=left(p_data->>'note',1000),badge_awarded_at=coalesce(badge_awarded_at,now()),badge_revoked_at=null,revision=revision+1 where enrollment_id=eid;
    update public.course_enrollments set completed_at=coalesce(completed_at,now()) where id=eid;
   else
    update public.course_completions set meeting_completed_at=null,meeting_completed_by=null,meeting_note=left(p_data->>'note',1000),badge_revoked_at=case when badge_awarded_at is not null then now() end,revision=revision+1 where enrollment_id=eid;
    update public.course_enrollments set completed_at=null where id=eid;
   end if;
   insert into public.course_audit(course_id,enrollment_id,actor_user_id,action,metadata) values(cid,eid,auth.uid(),'final_meeting_changed',jsonb_build_object('complete',coalesce((p_data->>'complete')::boolean,false),'note',left(p_data->>'note',1000),'previous_meeting_at',c.meeting_completed_at,'previous_actor',c.meeting_completed_by));
  end if;
  result:=private.course_snapshot(cid,uid);
  return result||jsonb_build_object('completion',(select to_jsonb(current_completion) from public.course_completions current_completion where enrollment_id=eid),'attempts',(select coalesce(jsonb_agg(x order by x.id),'[]') from(select * from public.course_attempts where enrollment_id=eid order by id desc limit 500 offset greatest(0,coalesce((p_data->>'attempt_offset')::integer,0)))x),
   'history',(select coalesce(jsonb_agg(x order by x.id),'[]') from(select id,action,actor_user_id,created_at,metadata from public.course_audit where enrollment_id=eid order by id desc limit 100)x));
 end if;
 raise exception 'Unknown management action';
end $$;
-- Only the server delivery adapter can acknowledge provider acceptance/failure.
create function private.course_invite_delivery(p_id uuid,p_delivery uuid,p_sent boolean) returns void language plpgsql security definer set search_path='' as $$
declare inv public.course_invites;begin
 select * into inv from public.course_invites where id=p_id and delivery_id=p_delivery for update;
 if inv.id is null or inv.status not in('pending','failed') then return;end if;
 update public.course_invites set status=case when p_sent then 'sent' else 'failed' end,send_status=case when p_sent then 'provider_accepted' else 'delivery_failed' end,last_send_at=now() where id=p_id;
 insert into public.course_audit(course_id,invite_id,action) values(inv.course_id,inv.id,case when p_sent then 'invite_provider_accepted' else 'invite_delivery_failed' end);
end $$;
create function public.dream_track(p_action text,p_data jsonb default '{}') returns jsonb language sql security invoker set search_path='' as $$select private.dream_track(p_action,p_data)$$;
create function public.dream_track_admin(p_org uuid,p_action text,p_data jsonb default '{}') returns jsonb language sql security invoker set search_path='' as $$select private.dream_track_admin(p_org,p_action,p_data)$$;
create function public.course_invite_delivery(p_id uuid,p_delivery uuid,p_sent boolean) returns void language sql security invoker set search_path='' as $$select private.course_invite_delivery(p_id,p_delivery,p_sent)$$;
revoke all on function private.course_normalize(text),private.course_code_hash(text,text),private.course_immutable(),private.course_snapshot(bigint,uuid,integer),private.course_recompute(bigint,uuid,integer),private.dream_track(text,jsonb),private.dream_track_admin(uuid,text,jsonb),private.course_invite_delivery(uuid,uuid,boolean),public.dream_track(text,jsonb),public.dream_track_admin(uuid,text,jsonb),public.course_invite_delivery(uuid,uuid,boolean) from public,anon,authenticated,service_role;
grant execute on function private.dream_track(text,jsonb),private.dream_track_admin(uuid,text,jsonb),public.dream_track(text,jsonb),public.dream_track_admin(uuid,text,jsonb) to authenticated;
grant usage on schema private to service_role;
grant execute on function private.course_invite_delivery(uuid,uuid,boolean),public.course_invite_delivery(uuid,uuid,boolean) to service_role;
do $$declare t text;begin foreach t in array array['course_settings','course_lessons','course_questions','course_attempts','course_completions','course_invites','course_audit','course_claim_limits']loop
 execute format('alter table public.%I enable row level security',t);
 execute format('revoke all on public.%I from public,anon,authenticated',t);
 execute format('grant all on public.%I to service_role',t);
end loop;end $$;

-- Exact approved bank; learner RPC omits both answer-key columns.
insert into public.course_questions(course_id,lesson_number,question_number,display_order,prompt,correct_answer,accepted_variants,review_start,review_end,scripture_reference)
select c.id,q.lesson,q.number,q.number,q.prompt,q.answer,array(select jsonb_array_elements_text(q.variants)),q.review_start,q.review_end,q.scripture from public.courses c cross join jsonb_to_recordset($bank$[{"lesson": 1, "number": 1, "prompt": "Champion Life believes there is a ________ in you.", "answer": "champion", "variants": ["a champion"], "review_start": 157, "review_end": 214, "scripture": null}, {"lesson": 1, "number": 2, "prompt": "God designed you for a ________.", "answer": "purpose", "variants": ["purpose in life"], "review_start": 165, "review_end": 196, "scripture": null}, {"lesson": 1, "number": 3, "prompt": "Champion Life’s first service on Denton Boulevard was in ________.", "answer": "June 2021", "variants": ["June of 2021", "2021"], "review_start": 262, "review_end": 327, "scripture": null}, {"lesson": 1, "number": 4, "prompt": "Before becoming Champion Life, the church was known as ________ Faith.", "answer": "Living", "variants": ["Living Faith"], "review_start": 278, "review_end": 327, "scripture": null}, {"lesson": 1, "number": 5, "prompt": "Champion Life’s two primary ministry focuses are ________ and children.", "answer": "outreach", "variants": ["Outreach"], "review_start": 505, "review_end": 567, "scripture": null}, {"lesson": 1, "number": 6, "prompt": "Champion Life wants to equip strong ________ so they can do the work of the ministry.", "answer": "believers", "variants": ["Believers", "strong believers"], "review_start": 593, "review_end": 635, "scripture": null}, {"lesson": 1, "number": 7, "prompt": "Champion Life’s threefold mission is to ________, reign, and reach.", "answer": "raise", "variants": ["Raise"], "review_start": 666, "review_end": 738, "scripture": null}, {"lesson": 1, "number": 8, "prompt": "The second part of Champion Life’s mission is to raise, ________, and reach.", "answer": "reign", "variants": ["Reign"], "review_start": 697, "review_end": 738, "scripture": null}, {"lesson": 1, "number": 9, "prompt": "The third part of Champion Life’s mission is to raise, reign, and ________.", "answer": "reach", "variants": ["Reach"], "review_start": 723, "review_end": 763, "scripture": null}, {"lesson": 1, "number": 10, "prompt": "Champion Life teaches that mankind was created to be fruitful, multiply, and take ________.", "answer": "dominion", "variants": ["Dominion"], "review_start": 706, "review_end": 730, "scripture": null}, {"lesson": 1, "number": 11, "prompt": "The purpose of Dream Track is to communicate Champion Life’s beliefs so that everyone can walk in ________.", "answer": "agreement", "variants": ["unity and agreement"], "review_start": 763, "review_end": 819, "scripture": null}, {"lesson": 1, "number": 12, "prompt": "Amos 3:3 asks, “Can two walk together unless they ________?”", "answer": "agree", "variants": ["are agreed"], "review_start": 771, "review_end": 802, "scripture": "Amos 3:3"}, {"lesson": 1, "number": 13, "prompt": "Dream Track teaches ________ core beliefs.", "answer": "seven", "variants": ["7"], "review_start": 833, "review_end": 862, "scripture": null}, {"lesson": 1, "number": 14, "prompt": "The first core belief covered in Dream Track is God’s ________.", "answer": "dream", "variants": ["Dream"], "review_start": 833, "review_end": 862, "scripture": null}, {"lesson": 1, "number": 15, "prompt": "In the teaching on God’s Dream, mankind was created in God’s image and likeness to rule, reign, and ________.", "answer": "dominate", "variants": ["take dominion", "exercise dominion"], "review_start": 942, "review_end": 1039, "scripture": null}, {"lesson": 1, "number": 16, "prompt": "Jesus taught that a person must be born ________ to see the Kingdom of God.", "answer": "again", "variants": ["born again"], "review_start": 1047, "review_end": 1092, "scripture": null}, {"lesson": 1, "number": 17, "prompt": "Champion Life teaches that being born again and being baptized in the Holy Spirit are two ________ works.", "answer": "separate", "variants": ["distinct"], "review_start": 1175, "review_end": 1231, "scripture": null}, {"lesson": 1, "number": 18, "prompt": "Champion Life teaches that the initial evidence of the baptism in the Holy Spirit is speaking in other ________.", "answer": "tongues", "variants": ["tongue"], "review_start": 1231, "review_end": 1287, "scripture": null}, {"lesson": 1, "number": 19, "prompt": "In the Abundant Life teaching, the word “prosper” is explained as moving or advancing ________.", "answer": "forward", "variants": ["advance forward", "moving forward"], "review_start": 1513, "review_end": 1613, "scripture": null}, {"lesson": 1, "number": 20, "prompt": "Champion Life’s theme Scripture is 2 Corinthians ________.", "answer": "2:14", "variants": ["2 14", "chapter 2 verse 14", "Second Corinthians 2:14"], "review_start": 1722, "review_end": 1792, "scripture": null}, {"lesson": 2, "number": 1, "prompt": "Champion Life teaches that God’s dream is to extend ________ to Earth through people.", "answer": "Heaven", "variants": ["heaven", "the Kingdom of Heaven"], "review_start": 396, "review_end": 444, "scripture": null}, {"lesson": 2, "number": 2, "prompt": "The four basic elements of the Gospel are God’s Dream, Satan’s Deception, Christ’s Substitution, and Man’s ________.", "answer": "Restoration", "variants": ["restoration"], "review_start": 612, "review_end": 636, "scripture": null}, {"lesson": 2, "number": 3, "prompt": "God created mankind in His image and likeness and gave mankind ________ over the earth.", "answer": "dominion", "variants": ["authority", "rule", "dominion"], "review_start": 643, "review_end": 693, "scripture": null}, {"lesson": 2, "number": 4, "prompt": "Champion Life teaches that every person was created with a unique purpose, passion, and ________.", "answer": "gifting", "variants": ["gift", "gifts", "gifting"], "review_start": 732, "review_end": 787, "scripture": null}, {"lesson": 2, "number": 5, "prompt": "Dream Track is designed to help each person find their ________ in God’s dream.", "answer": "place", "variants": ["place in God’s dream"], "review_start": 923, "review_end": 979, "scripture": null}, {"lesson": 2, "number": 6, "prompt": "God gave mankind freedom of ________.", "answer": "choice", "variants": ["free choice", "free will"], "review_start": 994, "review_end": 1037, "scripture": null}, {"lesson": 2, "number": 7, "prompt": "Jeremiah 29:11 is used in this lesson to show that God’s plans are for your ________.", "answer": "good", "variants": ["good", "benefit"], "review_start": 1045, "review_end": 1092, "scripture": "Jeremiah 29:11"}, {"lesson": 2, "number": 8, "prompt": "Ephesians 2:10 says believers are God’s workmanship, created in Christ Jesus for good ________.", "answer": "works", "variants": ["good works"], "review_start": 1053, "review_end": 1092, "scripture": "Ephesians 2:10"}, {"lesson": 2, "number": 9, "prompt": "The lesson teaches that life and death, blessing and cursing, involve personal ________.", "answer": "choices", "variants": ["choice", "decisions"], "review_start": 1099, "review_end": 1194, "scripture": null}, {"lesson": 2, "number": 10, "prompt": "Romans 12:2 is used to teach that renewing your mind helps you know God’s good, pleasing, and ________ will.", "answer": "perfect", "variants": ["perfect will"], "review_start": 1185, "review_end": 1219, "scripture": "Romans 12:2"}, {"lesson": 2, "number": 11, "prompt": "Adam lost both his royalty and his ________.", "answer": "authority", "variants": ["dominion", "authority"], "review_start": 1289, "review_end": 1330, "scripture": null}, {"lesson": 2, "number": 12, "prompt": "Satan’s deception often begins by causing people to question, “Did God really ________?”", "answer": "say", "variants": ["say that"], "review_start": 1386, "review_end": 1427, "scripture": null}, {"lesson": 2, "number": 13, "prompt": "The lesson teaches that people perish for a lack of ________.", "answer": "knowledge", "variants": ["knowledge of the Word"], "review_start": 1410, "review_end": 1457, "scripture": null}, {"lesson": 2, "number": 14, "prompt": "Isaiah 55 is used to teach that God sends His ________ to raise our thinking to His level.", "answer": "word", "variants": ["Word"], "review_start": 1503, "review_end": 1549, "scripture": "Isaiah 55"}, {"lesson": 2, "number": 15, "prompt": "Man’s journey through life is described as being filled with choices and ________.", "answer": "decisions", "variants": ["choices and decisions"], "review_start": 1580, "review_end": 1604, "scripture": null}, {"lesson": 2, "number": 16, "prompt": "Christ’s substitution means replacing one person with ________.", "answer": "another", "variants": ["another person"], "review_start": 2062, "review_end": 2092, "scripture": null}, {"lesson": 2, "number": 17, "prompt": "Jesus came as mankind’s substitute to redeem mankind and put people back into God’s ________.", "answer": "dream", "variants": ["plan", "perfect will", "God’s dream"], "review_start": 2085, "review_end": 2180, "scripture": null}, {"lesson": 2, "number": 18, "prompt": "The cross is described as the ________ of the Gospel, where a person must make a decision about Jesus.", "answer": "crucible", "variants": ["the crucible"], "review_start": 2449, "review_end": 2569, "scripture": null}, {"lesson": 2, "number": 19, "prompt": "Man’s restoration is defined as returning something to its original ________.", "answer": "condition", "variants": ["original condition"], "review_start": 3261, "review_end": 3307, "scripture": null}, {"lesson": 2, "number": 20, "prompt": "According to this lesson, Jesus restored believers to righteousness, royalty, authority, and the ability to rule, reign, and ________ God’s Kingdom.", "answer": "advance", "variants": ["extend", "advance", "extend and advance"], "review_start": 3275, "review_end": 3315, "scripture": null}, {"lesson": 3, "number": 1, "prompt": "Jesus said that unless a person is born ________, they cannot see the Kingdom of God.", "answer": "again", "variants": ["born again"], "review_start": 162, "review_end": 202, "scripture": null}, {"lesson": 3, "number": 2, "prompt": "Good works and righteous deeds do not make a person ________.", "answer": "righteous", "variants": ["right with God"], "review_start": 219, "review_end": 250, "scripture": null}, {"lesson": 3, "number": 3, "prompt": "To be born again is to get ________ Christ.", "answer": "in", "variants": ["in Christ"], "review_start": 250, "review_end": 297, "scripture": null}, {"lesson": 3, "number": 4, "prompt": "Colossians 3 teaches that the believer’s life is hidden with Christ in ________.", "answer": "God", "variants": ["God the Father"], "review_start": 304, "review_end": 398, "scripture": "Colossians 3"}, {"lesson": 3, "number": 5, "prompt": "Jeremiah’s picture of the potter and clay teaches that God does not merely clean a person up, He makes them ________.", "answer": "again", "variants": ["new again", "made again"], "review_start": 427, "review_end": 558, "scripture": null}, {"lesson": 3, "number": 6, "prompt": "Galatians 2:20 says, “It is no longer I who live, but ________ lives in me.”", "answer": "Christ", "variants": ["Jesus Christ"], "review_start": 600, "review_end": 665, "scripture": "Galatians 2:20"}, {"lesson": 3, "number": 7, "prompt": "Paul’s repeated terminology for the believer’s identity is “in ________.”", "answer": "Christ", "variants": ["Him", "Christ Jesus"], "review_start": 665, "review_end": 826, "scripture": null}, {"lesson": 3, "number": 8, "prompt": "The lesson teaches that the old man died and the ________ man was raised up.", "answer": "new", "variants": ["new man"], "review_start": 826, "review_end": 880, "scripture": null}, {"lesson": 3, "number": 9, "prompt": "Acts 17 says, “In Him we live, move, and have our ________.”", "answer": "being", "variants": ["existence"], "review_start": 911, "review_end": 965, "scripture": "Acts 17"}, {"lesson": 3, "number": 10, "prompt": "The believer’s primary identity should come from who they are in ________.", "answer": "Christ", "variants": ["Jesus", "Christ Jesus"], "review_start": 965, "review_end": 1086, "scripture": null}, {"lesson": 3, "number": 11, "prompt": "Romans 8:2 teaches that the law of the Spirit of Life in Christ Jesus sets believers free from the law of sin and ________.", "answer": "death", "variants": ["sin and death"], "review_start": 1277, "review_end": 1470, "scripture": "Romans 8:2"}, {"lesson": 3, "number": 12, "prompt": "The lesson compares the law of Life in Christ to the law of ________ that overcomes gravity.", "answer": "lift", "variants": ["aerodynamics", "lift"], "review_start": 1330, "review_end": 1405, "scripture": null}, {"lesson": 3, "number": 13, "prompt": "To live in the reality of the new creation, believers must boldly ________ who they are in Christ.", "answer": "confess", "variants": ["declare", "say"], "review_start": 1389, "review_end": 1446, "scripture": null}, {"lesson": 3, "number": 14, "prompt": "Romans 10:9–10 teaches that salvation involves believing in your heart and ________ with your mouth.", "answer": "confessing", "variants": ["confession", "confess"], "review_start": 1900, "review_end": 1976, "scripture": "Romans 10:9–10"}, {"lesson": 3, "number": 15, "prompt": "At the new birth, a person is translated out of the kingdom of darkness into the Kingdom of ________.", "answer": "God", "variants": ["Light", "the Kingdom of God"], "review_start": 1908, "review_end": 2054, "scripture": null}, {"lesson": 3, "number": 16, "prompt": "A person is a spirit, has a soul, and lives in a ________.", "answer": "body", "variants": ["physical body"], "review_start": 1999, "review_end": 2102, "scripture": null}, {"lesson": 3, "number": 17, "prompt": "At the new birth, the part of a person that becomes a brand-new creation is the ________.", "answer": "spirit", "variants": ["spirit man"], "review_start": 2070, "review_end": 2150, "scripture": null}, {"lesson": 3, "number": 18, "prompt": "Romans 12 and James 1 are used to teach that the soul changes through the renewing of the ________.", "answer": "mind", "variants": ["your mind"], "review_start": 2218, "review_end": 2447, "scripture": "Romans 12; James 1"}, {"lesson": 3, "number": 19, "prompt": "2 Corinthians 5:17 teaches that if anyone is in Christ, they are a new ________.", "answer": "creation", "variants": ["creature", "new creation"], "review_start": 2818, "review_end": 2953, "scripture": "2 Corinthians 5:17"}, {"lesson": 3, "number": 20, "prompt": "2 Corinthians 5:21 teaches that believers have been made the ________ of God in Christ.", "answer": "righteousness", "variants": ["righteousness of God"], "review_start": 2873, "review_end": 2986, "scripture": "2 Corinthians 5:21"}, {"lesson": 4, "number": 1, "prompt": "According to the lesson, the next step after the new birth is the baptism of the ________.", "answer": "Holy Spirit", "variants": ["Holy Ghost", "Spirit"], "review_start": 64, "review_end": 89, "scripture": null}, {"lesson": 4, "number": 2, "prompt": "The lesson teaches that praying in tongues and giving a public message in tongues are two ________ uses of tongues.", "answer": "different", "variants": ["separate", "distinct"], "review_start": 322, "review_end": 345, "scripture": null}, {"lesson": 4, "number": 3, "prompt": "Jesus told His disciples not to leave Jerusalem until they were endued with ________ from on high.", "answer": "power", "variants": ["supernatural power"], "review_start": 427, "review_end": 442, "scripture": null}, {"lesson": 4, "number": 4, "prompt": "Matthew 3:16 is used to show that Jesus was baptized with the ________.", "answer": "Holy Spirit", "variants": ["Spirit of God", "Holy Ghost"], "review_start": 557, "review_end": 616, "scripture": "Matthew 3:16"}, {"lesson": 4, "number": 5, "prompt": "Isaiah 12 speaks of drawing water with joy from the wells of ________.", "answer": "salvation", "variants": ["Salvation"], "review_start": 741, "review_end": 770, "scripture": "Isaiah 12"}, {"lesson": 4, "number": 6, "prompt": "Jesus said that out of the believer’s heart would flow rivers of ________ water.", "answer": "living", "variants": ["Living"], "review_start": 778, "review_end": 860, "scripture": null}, {"lesson": 4, "number": 7, "prompt": "The lesson contrasts the wells of salvation with rivers of Living Water to show two separate ________ of the Holy Spirit.", "answer": "workings", "variants": ["experiences", "operations", "works"], "review_start": 811, "review_end": 927, "scripture": null}, {"lesson": 4, "number": 8, "prompt": "Acts 1 teaches that believers would be baptized with the Holy Spirit not many ________ from then.", "answer": "days", "variants": ["days from now"], "review_start": 960, "review_end": 1031, "scripture": "Acts 1"}, {"lesson": 4, "number": 9, "prompt": "Acts 1:8 says believers receive ________ when the Holy Spirit comes upon them.", "answer": "power", "variants": ["dunamis", "supernatural power"], "review_start": 1277, "review_end": 1309, "scripture": "Acts 1:8"}, {"lesson": 4, "number": 10, "prompt": "In Acts 2, the believers were all filled with the Holy Spirit and began to speak with other ________.", "answer": "tongues", "variants": ["languages", "other tongues"], "review_start": 1324, "review_end": 1420, "scripture": "Acts 2"}, {"lesson": 4, "number": 11, "prompt": "According to Acts 2, the believers did the speaking while the Spirit gave the ________.", "answer": "utterance", "variants": ["language", "words"], "review_start": 1380, "review_end": 1429, "scripture": "Acts 2"}, {"lesson": 4, "number": 12, "prompt": "In Acts 19, Paul asked the disciples if they had received the Holy Spirit since they ________.", "answer": "believed", "variants": ["became believers"], "review_start": 1550, "review_end": 1676, "scripture": "Acts 19"}, {"lesson": 4, "number": 13, "prompt": "When Paul laid hands on the believers in Acts 19, they spoke with tongues and ________.", "answer": "prophesied", "variants": ["prophecy", "began to prophesy"], "review_start": 1710, "review_end": 1760, "scripture": "Acts 19"}, {"lesson": 4, "number": 14, "prompt": "1 Corinthians 14:2 teaches that the person speaking in a tongue is speaking to ________.", "answer": "God", "variants": ["the Lord"], "review_start": 1851, "review_end": 1979, "scripture": "1 Corinthians 14:2"}, {"lesson": 4, "number": 15, "prompt": "1 Corinthians 14 teaches that when speaking in tongues, the believer speaks ________ in the spirit.", "answer": "mysteries", "variants": ["divine mysteries"], "review_start": 1890, "review_end": 1955, "scripture": "1 Corinthians 14"}, {"lesson": 4, "number": 16, "prompt": "1 Corinthians 14:14 teaches that when a person prays in a tongue, their ________ prays.", "answer": "spirit", "variants": ["spirit man"], "review_start": 2165, "review_end": 2222, "scripture": "1 Corinthians 14:14"}, {"lesson": 4, "number": 17, "prompt": "Jude 20 says believers build themselves up on their most holy faith by praying in the ________.", "answer": "Holy Spirit", "variants": ["Spirit"], "review_start": 2278, "review_end": 2429, "scripture": "Jude 20"}, {"lesson": 4, "number": 18, "prompt": "Romans 8 teaches that the Holy Spirit helps believers because they do not always know what they should ________ for.", "answer": "pray", "variants": ["pray about"], "review_start": 2601, "review_end": 2742, "scripture": "Romans 8"}, {"lesson": 4, "number": 19, "prompt": "Luke 11 teaches that the Heavenly Father gives the Holy Spirit to those who ________.", "answer": "ask", "variants": ["ask Him"], "review_start": 3324, "review_end": 3468, "scripture": "Luke 11"}, {"lesson": 4, "number": 20, "prompt": "According to the lesson, the believer begins to speak and the Holy Spirit gives the ________.", "answer": "utterance", "variants": ["language", "words"], "review_start": 3523, "review_end": 3616, "scripture": null}, {"lesson": 5, "number": 1, "prompt": "Champion Life teaches that it is God’s ________ to heal.", "answer": "will", "variants": ["will to heal"], "review_sta